"""Human report plus chunked full signed parameter outcomes for public export."""
import sys,json,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.stvg_single_referdino_parameter_search256_common_v1 import ROOT,D,P,read,put,verify

def main():
 p=verify();r=read(P/'SELECTED_FIVE_ROW_RESULTS_PUBLIC.json');selection=read(P/'SELECTION_PUBLIC.json');assert read(P/'SELECTED_ROOT_AUDIT_PUBLIC.json')['status']=='pass';ledger=read(D/'GPU_LEDGER.json');export=P/'all_parameter_outcomes';export.mkdir(exist_ok=True);index=[];totalparents=totalreadouts=0
 for ds in ['hc2','vidstg']:
  for ph in ['coarse','fine']:
   z=read(P/ds/ph/'RESULTS_PUBLIC.json');summary={k:v for k,v in z.items()if k!='rows'};dest=export/f'{ds}_{ph}_SUMMARY.json';put(dest,summary);parts=[]
   for start in range(0,len(z['rows']),16):
    f=export/f'{ds}_{ph}_PARENTS_{start+1:03}_{min(start+16,128):03}.json';put(f,dict(dataset=ds,phase=ph,parents=z['rows'][start:start+16],all_signed_outcomes=True));parts.append(str(f.relative_to(P)))
   index.append(dict(dataset=ds,phase=ph,parents=128,readouts=len(z['definitions']),summary=str(dest.relative_to(P)),all_parent_parts=parts));totalparents+=128;totalreadouts+=128*len(z['definitions'])
 put(export/'INDEX.json',dict(status='all_four_phase_signed_outcomes_exported',parts=index,parent_phase_instances=totalparents,parent_readout_instances=totalreadouts,not_independent_confirmation=True))
 lines=['# Single ReferDINO: HC and Vid finite joint parameter search','', 'Both target datasets use the existing exposed128-parent panels and seed41. One frozen ReferDINO supplies the same eight boxes for E_Ref initialization and OPD supervision. E_Ref, Source, Strong, MBR, policy scales(0.05,0.25),32 candidates and8×256 temporary states are fixed. Network weights are not trained. The user allowed forward computation; the search reuses valid Source/expert inputs and actually replays the frozen decoder for every new optimizer path.','', '## Search and selection','', 'Coarse: lr0.003/0.01/0.03 × tau0.2/0.5;40-step paths read at10/20/30/40 and output alpha0.25/0.5/1/1.5/2. This is six optimizer paths and120 deterministic readouts per dataset. HC original40 baseline is reused after exact first-case replay; Vid40 baseline is actually run with all prior30 paths reproduced exactly. Each dataset then has one four-corner lr/tau sqrt2-neighborhood around its full-panel coarse winner, step±5 within1..40 and alpha±0.25. Coarse centers and original HC40/Vid30 configurations are retained.','', 'Output alpha scales the final center residual linearly and width/height residual in log ratio around E_Ref. It is a deterministic output parameter, not a new training rollout. Configuration selection maximizes complete vIoU across all128 parents; no video-specific stop, alpha or method switch. GT is offline after each whole phase is sealed; it is never used in adaptation.','', '## Selected development configurations','', '| Dataset | lr | tau | steps | output alpha | selected phase |','|---|---:|---:|---:|---:|---|']
 for ds,q in selection['datasets'].items():
  c=q['config'];lines.append(f"| {ds} | {c['lr']:.9g} | {c['tau']:.9g} | {c['steps']} | {c['output_alpha']:.3f} | {q['phase']} |")
 lines+=['','## Complete five-row evaluation','', '| Dataset / row | full vIoU % | tIoU % | fixed actual-node sIoU % | unobserved actual-node sIoU % |','|---|---:|---:|---:|---:|']
 for ds,g in r['directions'].items():
  for a,m in g['means'].items():lines.append(f"| {ds} / {a} | {100*m['v']:.6f} | {100*m['t']:.6f} | {100*m['fixed_actual_sIoU']:.6f} | {100*m['unobserved_actual_sIoU']:.6f} |")
 lines+=['','## Paired changes and signed tails','', '| Dataset / comparison | full vIoU delta pp [95% interval] | positive / negative / tied | worse than −5pp |','|---|---:|---:|---:|']
 for ds,g in r['directions'].items():
  for name,m in g['paired'].items():
   v,t=m['v'],m['tail'];lines.append(f"| {ds} / {name} | {v['mean']:+.6f} [{v['CI95'][0]:+.6f}, {v['CI95'][1]:+.6f}] | {t['positive']} / {t['negative']} / {t['unchanged']} | {t['below_minus5']} |")
  m=g['paired']['Full_minus_Without_spatial_adaptation'];lines+=['',ds+': worst retained adaptation cases '+', '.join(f"{v['alias']} {v['delta_pp']:+.4f}pp"for v in m['tail']['worst'])+'.']
  if ds=='vidstg':
   v=next(v for v in g['rows']if v['alias']=='BV041');lines.append(f"BV041 E_Ref+Strong {100*v['values']['Without_spatial_adaptation']['v']:.6f}%, original Full {100*v['historical']['original_Full']['v']:.6f}%, selected Full {100*v['values']['Full']['v']:.6f}%. The initialization itself remains fixed; optimizer tuning cannot be assumed to restore the old GroundingDINO-based E.")
 lines+=['','## Evidence scope','', 'These are development-selected results on repeatedly exposed parents. The reported paired bootstrap intervals describe the selected outcomes and do not adjust for the coarse/fine selection process. They do not establish independent generalization or a new independent Live-over-Fixed effect. Each direction has one fixed configuration shared by every video; all positive, negative, zero-intersection and no-update outcomes remain. If an adaptive winner is below E_Ref+Strong, that limitation is retained in SELECTION_PUBLIC.json rather than hidden. Source, Strong and E_Ref are verified unchanged.','', 'All candidates and signed parent scores are public under all_parameter_outcomes/INDEX.json, including every coarse/fine setting, controls, uncertainty, tails and parameter definitions. SELECTED_FIVE_ROW_RESULTS_PUBLIC.json contains the complete selected five-row parent outcomes. This search does not exhaust initialization strength/calibration, sampling scale, optimizer families or longer budgets; no conclusion of global optimality is made.','', '## Actual search cost','']
 for x in ledger['invocations']:lines.append(f"- {x['dataset']} / {x['phase']}: {x['new_primary_fits']} new primary fits, {x['new_updates']} updates (including {x['compatibility_updates']} compatibility updates), worker wall {x['wall_seconds']:.6f}s; peak allocated {x['peak_GPU_bytes']/2**30:.6f}GiB; failure={x['failure']}.")
 total=dict(new_primary_fits=sum(x['new_primary_fits']for x in ledger['invocations']),new_updates_including_compatibility=sum(x['new_updates']for x in ledger['invocations']),compatibility_updates=sum(x['compatibility_updates']for x in ledger['invocations']),worker_wall_seconds=sum(x['wall_seconds']for x in ledger['invocations']),new_RGB_Source_encoder_forwards=sum(x['new_RGB_or_Source_encoding_forwards']for x in ledger['invocations']),new_expert_forwards=sum(x['new_expert_forwards']for x in ledger['invocations']))
 lines+=['', 'Search costs are the full development matrix, including saving/auditing overhead; they are not single-query deployment latency. Prior Source/ReferDINO cache creation and full-input method profiles are inherited and are not free. No new expert or Source RGB encoding was necessary for the parameter paths. All network weights remain frozen; per-query temporary states and Adam are reset for each path.','', 'One bounded coarse/fine round is complete. No automatic additional grid/seed/domain extension, checkpoint replacement or CURRENT/MAIN/PAPER promotion follows this report.']
 put(P/'SEARCH_COST_PUBLIC.json',dict(**total,invocations=ledger['invocations']));(P/'REPORT.md').write_text('\n'.join(lines)+'\n');print('TUNING_REPORT_AND_ALL_OUTCOMES_EXPORTED',total,flush=True)
if __name__=='__main__':main()
